def lru_hits(keys, capacity):
    cache = []
    hits = 0
    for k in keys:
        if k in cache:
            hits += 1
            cache.remove(k)
            cache.append(k)
        else:
            if len(cache) >= capacity:
                cache.pop(0)
            cache.append(k)
    return hits

ex_fn_merge.solution:
def merge_intervals(intervals):
    if not intervals:
        return []
    xs = sorted([list(i) for i in intervals])
    out = [xs[0]]
    for s, e in xs[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

