ex_fn_interval_cover.solution:
def covered_length(intervals):
    if not intervals:
        return 0
    xs = sorted([list(i) for i in intervals])
    out = [xs[0]]
    for s, e in xs[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    total = 0
    for s, e in out:
        total += e - s
    return total

