def valid_path(states):
    if not states or states[0] != 0:
        return False
    table = {0: [1, 4], 1: [2, 4, 5], 2: [3, 5], 3: [6]}
    for a, b in zip(states, states[1:]):
        if b not in table.get(a, []):
            return False
    return True

ex_fn_lru_v.solution:
def lru_trace(keys, capacity):
    cache = []
    flags = []
    for k in keys:
        if k in cache:
            flags.append(1)
            cache.remove(k)
            cache.append(k)
        else:
            flags.append(0)
            if len(cache) >= capacity:
                cache.pop(0)
            cache.append(k)
    return [flags, cache]

