ex_fn_merge_v.solution:
def largest_gap(intervals, horizon):
    xs = sorted([list(i) for i in intervals])
    out = []
    for s, e in xs:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    best, cur = 0, 0
    for s, e in out:
        if s > cur:
            best = max(best, s - cur)
        cur = max(cur, e)
    return max(best, horizon - cur)

ex_fn_hotkey_v.solution:
def hot_report(keys, n=2):
    if not keys:
        return [[], 0.0]
    counts = {}
    for k in keys:
        counts[k] = counts.get(k, 0) + 1
    order = sorted(counts, key=lambda k: (-counts[k], k))
    top = order[:n]
    share = round(sum(counts[k] for k in top) / len(keys), 4)
    return [top, share]
